defmodule ExNVR.Devices.Cameras.Timezones do
  @moduledoc false

  # generated by scripts/gen_timezones.exs
  @path Path.expand("../../../../priv/timezones.json", __DIR__)
  @external_resource @path
  @timezones @path |> File.read!() |> JSON.decode!()

  @doc """
  Get the POSIX TZ string (IEEE 1003.1) of an IANA timezone, e.g. "Europe/Dublin" => "GMT0IST,M3.5.0/1,M10.5.0"
  """
  @spec posix(String.t()) :: {:ok, String.t()} | :error
  def posix(timezone) do
    case Map.fetch(@timezones, timezone) do
      {:ok, [posix, _country]} -> {:ok, posix}
      :error -> :error
    end
  end

  @doc """
  Get the ISO 3166 country code of an IANA timezone, nil for non geographic timezones (e.g. UTC).
  """
  @spec country(String.t() | nil) :: String.t() | nil
  def country(timezone) do
    case Map.fetch(@timezones, timezone) do
      {:ok, [_posix, country]} -> country
      :error -> nil
    end
  end
end
